import {refreshOrbs,setOrbHostState,orbDiagnostics} from './orbs.js';
import {dictationFiles,ModelDownloads,downloadProgress,modelSetupMarkup} from './model-setup.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,page='dictation',query='',searchOpen=false,libraryTab='all',note=null,noteTab='notes',settingPage='General',onboardStep=0,hostVisible=true,lowPower=false,selectedFolder='',busyCount=0,seq=0;
const pending=new Map(); let toastTimer, captionTheme, modelMaintenance=false;
function call(action,args={}){return new Promise((resolve,reject)=>{const id=String(++seq);pending.set(id,{resolve,reject});window.chrome.webview.postMessage({id,action,args});});}
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function busy(label='Thinking…',mode='searching'){return `<span class="busy"><canvas data-orb="${mode}" aria-hidden="true"></canvas><span>${escape(label)}</span></span>`;}
const modelUi={escape,size,busy,name:modelName};
const modelDownloads=new ModelDownloads({
 download:async file=>{state.models=await call('modelDownload',{file});},
 cancel:()=>call('modelCancel'),
 installed:file=>state?.models.some(m=>m.file===file&&m.installed),
 changed:refreshModelDownloads,
 failed:error=>notify(error.message)
});
function modelSetup(){return `<div class="model-setup" data-model-setup>${modelSetupMarkup(state.models,modelDownloads,modelUi,modelMaintenance)}</div>`;}
function refreshModelDownloads(progress){
 if(!state)return;
 if(progress){
  $$('[data-download]').filter(el=>el.dataset.download===progress.file).forEach(el=>{el.innerHTML=downloadProgress(progress,modelUi);el.hidden=!el.innerHTML;});
 }else{
  $$('[data-model-setup]').forEach(el=>{el.innerHTML=modelSetupMarkup(state.models,modelDownloads,modelUi,modelMaintenance);});
  $$('[data-model-ready]').forEach(el=>el.textContent=dictationFiles.every(file=>modelDownloads.ready(file))?'Ready to dictate':'Finish your one-time setup');
  $$('[data-action="repairSetup"]').forEach(el=>el.disabled=modelDownloads.busy||modelMaintenance);
 }
 refreshOrbs();
}
async function run(action,args={},refresh=true){try{const result=await call(action,args);if(result?.settings){state=result;if(refresh)render();}return result;}catch(e){notify(e.message);throw e;}}
function button(label,action,args='',kind=''){return `<button class="${kind}" data-action="${action}" ${args}>${label}</button>`;}
function date(value){return new Date(value).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'});}
function time(value){return new Date(value).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});}
function size(n){return n>1e9?(n/1e9).toFixed(2)+' GB':Math.ceil(n/1e6)+' MB';}
function duration(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');}
function icon(path){return `<span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg></span>`;}
const paths={dictation:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3"/>',notetaker:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>',insights:'<path d="M4 3v18h17M8 15V9h3v6M15 15V5h3v10"/>',dictionary:'<path d="M7 3h10l3 4v14H7zM4 6v12M10 10h7M10 14h5"/>',snippets:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 13 13M8 16 21 3"/>',style:'<path d="M3 5h12M9 5v15M15 10h7M18.5 10v10"/>',transforms:'<path d="m3 20 13-13 4 4L7 24M15 2v3M20 5h3M6 3v6M3 6h6"/>',scratchpad:'<path d="M4 4h16v12h-8l-5 4v-4H4zM8 8h8M8 12h4"/>'};
const titles={dictation:'Dictation',notetaker:'Notetaker',insights:'Insights',dictionary:'Dictionary',snippets:'Snippets',style:'Style',transforms:'Transforms',scratchpad:'Scratchpad',shared:'Shared library'};
function navigation(){ $('#navigation').innerHTML=Object.keys(paths).map(p=>`<button class="nav ${page===p?'active':''}" data-page="${p}">${icon(paths[p])}${titles[p]}${p==='notetaker'?'<span class="badge">New!</span>':''}</button>`).join(''); }
function applyTheme(){
 const t=state.settings.theme, dark=(t==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):t)==='dark';
 document.documentElement.dataset.theme=dark?'dark':'light';
 $('#theme').innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${dark?'<path d="M20 14a8 8 0 0 1-10-10 8 8 0 1 0 10 10Z"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>'}</svg>`;
 $('#theme').setAttribute('aria-label',dark?'Dark mode; switch to light mode':'Light mode; switch to dark mode');
 $('#theme').title=dark?'Switch to light mode':'Switch to dark mode';
 if(captionTheme!==dark){captionTheme=dark;call('captionTheme',{dark}).catch(()=>{});}
 refreshOrbs();
}
function head(title,actions=''){return `<div class="page-head"><h1>${title}</h1><div class="row">${actions}</div></div>`;}
function render(){if(!state)return;applyTheme();navigation();if(!state.settings.onboarded){onboarding();return;}$('#main').innerHTML='<div class="content">'+({dictation:home,notetaker:meetings,insights, dictionary:()=>library('dictionary'),snippets:()=>library('snippet'),style,transforms,scratchpad,shared}[page]||home)()+'</div>';recordingStatus();refreshOrbs();}
function home(){
 const items=state.history.filter(h=>(h.text+' '+h.raw+' '+h.target).toLowerCase().includes(query.toLowerCase()));
 let previous='';
 return head(`Hey, get back into the flow with <span class="key shortcut-highlight">${escape(state.settings.toggleShortcut)}</span>`,button('Import audio','importAudio'))+
 `<div class="dictation-grid"><section><div class="hero warm dictation-hero"><div class="hero-copy"><h2>Make Murmur sound like <em>you</em></h2><p>Set up different writing styles for different apps.</p><button data-page="style" class="primary">Set your style</button></div><canvas data-orb="searching" data-size="64" data-paused="true" aria-hidden="true"></canvas></div><div class="row spread"><h3>Dictation history</h3><div>${button('Start dictation','record','data-mode="dictation"','quiet small')}${button('⌕ Search','search','','quiet small')}</div></div>${searchOpen?`<input class="search" id="search-input" aria-label="Search history" value="${escape(query)}" placeholder="Search past transcripts">`:''}`+
 (items.length?items.map(h=>{let day=date(h.created),heading=day!==previous?`<div class="date-label">${day}</div>`:'';previous=day;return heading+`<article class="history-row"><div class="history-time">${time(h.created)}</div><div class="grow"><div class="history-text">${escape(h.text||h.error||'No speech detected.')}</div>${h.error?`<p class="inline-error">${escape(h.error)}</p>`:''}<div class="history-actions">${button('Copy','copyHistory',`data-id="${h.id}"`)}${button('Retry insertion','retryPaste',`data-id="${h.id}"`)}${h.audio?button('Play','play',`data-id="${h.id}"`)+button('Retry transcription','retryTranscription',`data-id="${h.id}"`):''}${button('Delete','deleteHistory',`data-id="${h.id}"`,'quiet danger')}<span class="muted">${escape(h.target)} · ${duration(h.duration)} · ${((h.transcriptionMs+h.cleanupMs)/1000).toFixed(1)}s processing</span></div></div></article>`}).join(''):`<div class="empty">${icon(paths.dictation)}<h2>Your first words belong here.</h2><p>Start a dictation or import a recording. Completed text appears here for copying and recovery.</p></div>`)+`</section><aside class="voice-stats">${stats()}<div class="voice-tip"><h3>Your voice, everywhere.</h3><p>Double-tap Caps Lock to begin. Tap Caps Lock once to finish.</p><p class="muted">The recording bar stays hidden until you need it.</p></div></aside></div>`;
}
function stats(){const words=state.history.reduce((n,h)=>n+h.text.split(/\s+/).filter(Boolean).length,0),seconds=state.history.reduce((n,h)=>n+h.duration,0);return `<div class="stats"><div><strong>${words.toLocaleString()}</strong><span>total words</span></div><div><strong>${seconds?Math.round(words/seconds*60):'—'}</strong><span>words per minute</span></div><div><strong>${state.history.length}</strong><span>dictations</span></div></div>`;}
function library(kind){const isDict=kind==='dictionary',entries=(isDict?state.dictionary:state.snippets).filter(e=>(libraryTab==='all'||(libraryTab==='shared'?e.shared:!e.shared))&&(e.trigger+' '+e.value).toLowerCase().includes(query.toLowerCase()));return head(isDict?'Dictionary':'Snippets',button('Export','exportEntries',`data-kind="${kind}"`,'quiet')+button('Import','importEntries',`data-kind="${kind}"`,'primary')+button('Add new','editEntry',`data-kind="${kind}"`,'primary'))+`<div class="tabs">${['all','personal','shared'].map(v=>button(v==='all'?'All':v==='personal'?'Personal':'Shared library','libraryTab',`data-value="${v}"`,libraryTab===v?'active':'')).join('')}<div class="tools">${button('⌕','search','','icon')}${button('↕','sortLibrary','','icon')}</div></div>${searchOpen?`<input class="search" id="search-input" aria-label="Search library" value="${escape(query)}" placeholder="Search ${isDict?'vocabulary':'snippets'}">`:''}`+(entries.length?entries.map(e=>`<div class="table-row"><div class="word">${escape(e.trigger)}${e.shared?'<div class="eyebrow">Shared</div>':''}</div><p>${escape(e.value)}</p><div class="row">${button('Edit','editEntry',`data-kind="${kind}" data-id="${e.id}"`,'small')}${button('×','deleteEntry',`data-kind="${kind}" data-id="${e.id}"`,'quiet danger')}</div></div>`).join(''):`<div class="hero warm library-hero"><h2>${isDict?'Murmur spells the way <em>you</em> do.':'The stuff you shouldn’t have to re-type.'}</h2><p>${isDict?'Add personal terms, company jargon, and uncommon names so they’re spelled right in your dictations and notes.':'Turn a phrase into your most-used text. Say the shortcut and Murmur fills in the rest, exactly as you saved it.'}</p><div class="library-actions">${button(isDict?'Add new word':'Add new snippet','editEntry',`data-kind="${kind}"`,'primary')}<span class="library-examples">${isDict?'Names · Technical terms · Corrections':'Signatures · Links · Templates'}</span></div></div>`);}
function style(){return head('Style')+`<div class="tabs"><button class="active">Auto cleanup</button></div><h2 class="serif">Make Murmur sound like you.</h2><p class="muted">Auto cleanup controls how much Murmur rewrites. Tone below controls how the result sounds. Names, numbers, links, email addresses and code are protected.</p><div class="choices">${[['none','None','Keep the raw transcription, with your dictionary and snippets.'],['light','Light','Remove fillers and repetitions. Add punctuation with minimal changes.'],['medium','Medium','Rephrase for clarity while preserving the intended meaning.']].map(([v,t,d])=>`<button class="choice ${state.settings.cleanup===v?'selected':''}" data-action="setCleanup" data-value="${v}"><strong>${t}</strong>${d}<small>${v==='none'?'No writing model needed':'Runs locally unless you enable a provider'}</small></button>`).join('')}</div><div class="spacer"></div><section class="tone-settings"><h2>Tone by app</h2><p class="muted">Murmur chooses the row for the app you’re dictating into. For example, Gmail uses Email; WhatsApp uses Personal messaging. Everything else uses Default tone.</p>${state.settings.cleanup==='none'?'<div class="notice">Tone is paused while Auto cleanup is set to None. Choose Light or Medium to apply it.</div>':'<p class="footer-note">Light keeps tone changes subtle. Medium allows more rewording. Very short replies may stay as spoken to finish faster.</p>'}${!state.settings.detectWritingContext?'<div class="notice">Writing context detection is off. The default tone applies unless you add an app override.</div>':''}${settingRow('Default tone','Used for documents and apps Murmur does not recognize.',selectSetting('style',['formal','casual','very casual','excited']))}${settingRow('Email','Used for recognized email apps. Spoken greetings and sign-offs get their own lines.',selectSetting('emailStyle',['formal','casual','excited']))}${settingRow('Personal messaging','Used for personal chats such as WhatsApp and Discord.',selectSetting('personalStyle',['formal','casual','very casual']))}${settingRow('Work messaging','Used for workplace chats such as Slack and Teams.',selectSetting('workStyle',['formal','casual','excited']))}</section><div class="spacer"></div><div class="row spread"><h3>App overrides</h3>${button('Add app','appStyle')}</div>${state.settings.appStyles.map((s,i)=>`<div class="table-row"><span>${escape(s.process)}</span><span>${escape(s.category)} · ${escape(s.style)}</span>${button('Remove','removeAppStyle',`data-index="${i}"`,'quiet danger')}</div>`).join('')}<p class="footer-note">Email, messaging and documents are detected from the focused app and window title. Unknown contexts use your default style. App overrides take priority.</p>`;}
function transforms(){return head('Transforms <span class="badge">Local AI</span>',button('Create new','editTransform','','primary'))+`<div class="hero"><h2 class="serif">A little more like you.</h2><p>Polish a draft, structure a prompt, or apply your own instructions. Paste text into Scratchpad, then choose a transform.</p>${button('Open Scratchpad','openScratchpad','','primary')}</div><div class="stack">${[{id:'polish',name:'Polish',prompt:'Improve clarity and conciseness without changing the meaning.'},{id:'prompt',name:'Prompt Engineer',prompt:'Rewrite this as a clear, structured prompt with context, task and constraints. Do not invent requirements.'},...state.transforms].map(t=>`<div class="note-row"><div class="grow"><h3>${escape(t.name)}</h3><p>${escape(t.prompt.slice(0,180))}</p></div>${button('Use','useTransform',`data-id="${t.id}"`)}${!['polish','prompt'].includes(t.id)?button('Edit','editTransform',`data-id="${t.id}"`,'quiet'):''}</div>`).join('')}</div>`;}
function scratchpad(){return head('Scratchpad',button('Undo last transform','undoTransform','','quiet')+button('Copy','copyScratchpad')+button('Polish','polishScratchpad','','primary'))+`<textarea class="editor" id="scratchpad-editor" aria-label="Scratchpad" placeholder="A place to think, dictate, and rewrite…">${escape(state.scratchpad)}</textarea><p class="footer-note">Saved locally as you type. Voice Command: select text in another app, hold <span class="key">${escape(state.settings.commandShortcut)}</span>, speak your instruction and release.</p><div id="transform-result"></div>`;}
function meetings(){if(note)return noteView();let notes=state.meetings.filter(m=>(!selectedFolder||m.folderId===selectedFolder)&&m.title.toLowerCase().includes(query.toLowerCase()));return head('Notetaker',button('⚙','notetakerSettings','','icon')+button('Import recording','importAudio','data-mode="meeting"')+button('Start Notetaker','record','data-mode="meeting"','primary'))+`<div class="row spread"><h3>Upcoming meetings</h3>${button('Calendar connections','calendarSettings','','small quiet')}</div>${upcomingMeetings()}<div class="tabs">${button('Past notes','notesTab','','active')}${button('Folders','foldersTab')}<div class="tools">${button('⌕','search','','icon')}</div></div>${searchOpen?`<input class="search" id="search-input" aria-label="Search meetings" value="${escape(query)}" placeholder="Search past notes">`:''}${selectedFolder?`<div class="notice row spread">${escape(state.folders.find(f=>f.id===selectedFolder)?.name)}${button('Show all','clearFolder','','small')}</div>`:''}<section>${notes.length?notes.map(m=>`<div class="note-row"><div class="note-icon">▤</div><div class="grow"><button class="note-title" data-action="openNote" data-id="${m.id}"><h3>${escape(m.title)}</h3></button><p>${date(m.created)} · ${duration(m.duration)} · ${escape(m.status)}</p></div>${button('Open','openNote',`data-id="${m.id}"`,'small quiet')}</div>`).join(''):`<div class="empty">${icon(paths.notetaker)}<h2>Be here for the conversation.</h2><p>Record a meeting or voice note. Your transcript, summary and personal thoughts stay together.</p>${button('New typed note','newNote')}</div>`}</section><div class="ask-box"><input id="ask-input" aria-label="Ask about your meetings" placeholder="Ask a question about your past meetings…">${button('Ask','ask','','primary')}</div><div id="answer"></div>`;}
function upcomingMeetings(){return (state.calendarEvents||[]).length?state.calendarEvents.map(e=>`<div class="note-row"><div class="grow"><h3>${escape(e.title)}</h3><p>${date(e.start)} · ${time(e.start)}</p></div>${e.joinUrl?button('Join','joinEvent',`data-id="${escape(e.id)}"`,'small'):''}${button('Record','recordEvent',`data-id="${escape(e.id)}"`,'small primary')}</div>`).join(''):'<div class="notice">Connect your calendar in Settings, or start an unscheduled meeting or voice note. Recording begins only when you choose Start.</div>';}
function noteView(){const recording=state.recording.state==='recording'&&state.recording.id===note.id;return `<div class="row spread"><button class="quiet" data-action="backNotes">← All notes</button><div class="row">${button('Export','exportMeeting',`data-id="${note.id}"`)}${button(recording?'Stop recording':'Resume recording',recording?'stop':'record',`data-mode="meeting" data-meeting-id="${note.id}"`,recording?'recording record-button':'primary')}</div></div><div class="spacer"></div><input id="note-title" value="${escape(note.title)}" aria-label="Note title" style="width:100%;font-size:28px;border:0;background:transparent;padding:0;font-weight:550"><p class="muted">${date(note.created)} · ${duration(note.duration)} · ${escape(note.status)}</p><div class="row"><select id="note-folder" aria-label="Folder"><option value="">No folder</option>${state.folders.map(f=>`<option value="${f.id}" ${note.folderId===f.id?'selected':''}>${escape(f.name)}</option>`).join('')}</select>${button('Delete note','deleteMeeting',`data-id="${note.id}"`,'quiet danger')}</div><div class="tabs">${['notes','summary','transcript','ask'].map(t=>button(t==='notes'?'My notes':t[0].toUpperCase()+t.slice(1),'noteTab',`data-value="${t}"`,noteTab===t?'active':'')).join('')}</div>${noteTab==='notes'?`<textarea class="editor" id="note-editor" aria-label="Personal notes" placeholder="Your private thoughts. These stay separate from the generated summary.">${escape(note.notes)}</textarea>`:noteTab==='summary'?`<div class="row spread"><span class="muted">${note.summaryEdited?'Edited by you':'Generated locally from the transcript'}</span>${button(note.summary?'Regenerate':'Generate summary','summarize',`data-id="${note.id}"`)}</div><textarea class="editor" id="summary-editor" aria-label="Meeting summary" placeholder="A summary appears after transcription. You can also generate one here.">${escape(note.summary)}</textarea>`:noteTab==='transcript'?`<div class="row spread"><input id="transcript-search" placeholder="Find in transcript" aria-label="Find in transcript">${button('Rename speaker','speakerName')}${button('Stop playback','stopPlayback','','small')}</div><p class="footer-note">Labels identify the microphone and system-audio tracks. Enable speaker identification in Notetaker settings to distinguish people on the same track. Mixed turns are marked when uncertain.</p><div id="segments">${segments(note.segments||[])}</div>${(note.audio||[]).map((_,i)=>button(`Play track ${i+1}`,'play',`data-kind="meeting" data-id="${note.id}" data-track="${i}"`,'small')).join('')}`:`<div class="ask-box"><input id="ask-input" aria-label="Ask about this meeting" placeholder="What were the next steps?">${button('Ask','ask',`data-meeting-id="${note.id}"`,'primary')}</div><div id="answer"></div>`}`;}
function segments(list){return list.map(s=>`<div class="segment"><span class="key">${duration(s.start)}</span> <strong>${escape(s.speaker)}</strong><p>${escape(s.text)}</p></div>`).join('');}
function insights(){return head('Insights')+stats()+`<div class="hero"><h2 class="serif">A little less time at the keyboard.</h2><p>Your figures come from your saved dictations. No usage data leaves this PC.</p></div><h3>Recent processing time</h3>${state.history.slice(0,15).map(h=>`<div class="table-row"><span>${date(h.created)} ${time(h.created)}</span><span>Speech ${(h.transcriptionMs/1000).toFixed(2)}s · cleanup ${(h.cleanupMs/1000).toFixed(2)}s</span><span>${duration(h.duration)} audio</span></div>`).join('')||'<p class="muted">Make a dictation to see measured results.</p>'}`;}
function shared(){return head('Shared library',button('Sync now','sync','','primary'))+`<h2 class="serif">Words you use together.</h2><p>Use a shared Windows or synchronized folder for vocabulary, snippets and selected meeting folders. Mark only the items you want to share.</p><div class="notice">Only selected shared entries and meeting folders are synchronized. Shared meetings include their transcript and summary. Personal notes and audio stay private. Windows or your folder provider controls access.</div>${button('Choose shared folder','chooseSharedFolder')}<p class="muted">${escape(state.settings.sharedFolder||'No folder selected')}</p><p class="footer-note">Sync uses the same configured folder on each PC. Edits and deletions merge by timestamp. Network folders support locking; cloud-folder conflicts may need another sync. Hosted invitations and accounts are not configured.</p>`;}

function settingRow(title,description,control){return `<div class="setting-row"><div><label>${title}</label>${description?`<p class="muted">${description}</p>`:''}</div>${control}</div>`;}
function selectSetting(key,options){return `<select data-setting="${key}" aria-label="${key}">${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${escape(v)}" ${state.settings[key]===v?'selected':''}>${escape(l)}</option>`;}).join('')}</select>`;}
function checkSetting(key){return `<input type="checkbox" data-setting="${key}" aria-label="${key}" ${state.settings[key]?'checked':''}>`;}
function textSetting(key,type='text'){return `<input type="${type}" data-setting="${key}" aria-label="${key}" value="${escape(state.settings[key])}">`;}
function modelName(file){return ({'moonshine-base-en':'English dictation','ggml-silero-v6.2.0.bin':'Speech detection','qwen2.5-1.5b-instruct-q4_k_m.gguf':'Writing & email polish','speaker-segmentation.int8.onnx':'Speaker detection','3dspeaker_speech_eres2net_base_sv_zh-cn_3dspeaker_16k.onnx':'Speaker recognition'})[file]||'Additional component';}
function speakerSetup(){const files=['speaker-segmentation.int8.onnx','3dspeaker_speech_eres2net_base_sv_zh-cn_3dspeaker_16k.onnx'];return files.every(file=>state.models.some(m=>m.file===file&&m.installed))?'':`<div class="notice">Speaker identification needs an optional 41 MB download. ${button('Set up speaker identification','downloadSpeakers')}</div>`;}
function modelsView(){const ready=dictationFiles.every(file=>modelDownloads.ready(file));return `<h3>One setup. Ready for wherever you write.</h3><p class="muted">Download each component using its arrow, or choose Download all below. Murmur uses one English speech engine and formats emails and messages using your Style preferences.</p><div class="notice"><strong data-model-ready>${ready?'Ready to dictate':'Finish your one-time setup'}</strong><p>Speech recognition and writing polish work together on this PC. No subscription or model picking.</p></div>${modelSetup()}<p class="footer-note">Components load when needed and unload after inactivity. The thinking orb animates only while there is work to show, with a lower frame rate on battery.</p><div class="row wrap">${button('Repair dictation setup','repairSetup',modelDownloads.busy||modelMaintenance?'disabled':'','quiet')}${button('Unload writing component','unload','','quiet')}</div>`;}


async function openSettings(name='General'){
 settingPage=name;$('#settings-nav').innerHTML=`<div class="eyebrow">Settings</div>${['General','System','Models','Notetaker','Calendar','Shared library','MCP','Providers','Data and privacy','Updates'].map(n=>`<button data-setting-page="${n}" class="${n===name?'active':''}">${n==='Models'?'Dictation setup':n}</button>`).join('')}<footer>Murmur ${escape(state.version)}<br>${escape(state.architecture)} · N3mo Studio</footer>`;
 const s=state.settings;let body='';
 if(name==='General')body=`<div class="settings-group">${settingRow('Push to talk','Hold these keys and speak.',textSetting('holdShortcut'))}${settingRow('Hands-free','Double-tap Caps Lock to start; tap Caps Lock once to finish. Use Shift + Caps Lock to toggle capitalization. You can choose another shortcut.',textSetting('toggleShortcut'))}${settingRow('Voice command','Select text, hold this shortcut, and speak your edit.',textSetting('commandShortcut'))}${settingRow('Microphone','Changes apply to the next recording.',`<select id="device-select" data-setting="microphone"><option value="default">System default</option></select>`)}${settingRow('Microphone test','A visible 5-second test; test audio is deleted.',button('Test input','testMic'))}<div class="meter"><i id="mic-level"></i></div>${settingRow('Language','This release focuses on fast English dictation.','<span>English</span>')}${settingRow('Theme','',selectSetting('theme',['light','dark','system']))}</div><p class="footer-note">Duplicate and Windows-reserved shortcuts are rejected. Other apps that install keyboard hooks may still conflict; choose another combination if needed.</p>`;
 if(name==='System')body=`<div class="settings-group">${settingRow('Open at sign in','Start quietly in the Windows tray.',checkSetting('startAtLogin'))}${settingRow('Bar position','Follows the pointer’s monitor.',selectSetting('overlayEdge',['bottom','left','right']))}${settingRow('Thinking orb','Animate while working, follow Windows, or keep the orb still. Animation stops when hidden.',selectSetting('orbAnimation',[['on','Animated'],['system','Follow Windows'],['off','Still']]))}${settingRow('Submit after insertion','Off by default. When enabled, sends Enter after a successful paste.',checkSetting('submitAfterInsert'))}</div><div class="notice">The recording bar appears only during recording and processing. Double-tap Caps Lock to start, then tap Caps Lock once to stop. Closing the main window keeps Murmur in the tray. Right-click the tray icon to quit. Elevated apps and fields that do not expose editing support may require manual paste.</div>`;
 if(name==='Models')body=modelsView();
 if(name==='Notetaker')body=`<div class="settings-group">${settingRow('Capture system audio','Records the Windows default output alongside your microphone. Start recording explicitly.',checkSetting('meetingSystemAudio'))}${settingRow('Identify speakers','Optional. Distinguishes people within one audio source. Adds processing time and memory use; labels can be renamed.',checkSetting('identifySpeakers'))}${speakerSetup()}${settingRow('Recording limit (minutes)','Stops safely and saves audio at the limit. Maximum 180 minutes.',textSetting('meetingLimitMinutes','number'))}</div><div class="notice">Your typed notes stay separate from generated summaries. Speaker labels distinguish microphone and system audio; you can rename them. Enable speaker identification in Notetaker settings to distinguish people on the same track. Mixed turns are marked when uncertain.</div>`;
 if(name==='Calendar')body=`${settingRow('Meeting reminders','Notify five minutes before meetings in your last refreshed calendar. Recording never starts automatically.',checkSetting('calendarReminders'))}<p>Connect Google or Outlook using your own OAuth app registration. Calendar access is read-only. ${(state.calendarConnections||[]).filter(c=>c.connected).map(c=>escape(c.provider)+' connected').join(' · ')}</p><div class="settings-form"><label>Provider<select id="calendar-provider"><option value="google">Google Calendar</option><option value="microsoft">Outlook Calendar</option></select></label><label>OAuth client ID<input id="calendar-client" autocomplete="off"></label><label>Google desktop client secret (if required)<input id="calendar-secret" type="password" autocomplete="off"></label></div><div class="row wrap">${button('Connect','calendarConnect','','primary')}${button('Refresh','calendarRefresh')}${button('Disconnect','calendarDisconnect','','quiet')}</div><div class="notice">A provider client registration and your browser consent are required. You can use all local note features without connecting a calendar.</div><div id="calendar-result"></div>`;
 if(name==='Shared library')body=shared().replace(/<div class="page-head">[\s\S]*?<\/div><\/div>/,'');
 if(name==='MCP')body=`<div class="settings-group">${settingRow('Enable local MCP','Allows an explicitly configured MCP client to read meeting summaries and transcripts.',checkSetting('mcpEnabled'))}</div><p>Configure a stdio server in your MCP client:</p><pre class="notice">${escape(JSON.stringify({mcpServers:{murmur:{command:state.mcpCommand.replace(/ --mcp$/,''),args:['--mcp']}}},null,2))}</pre><p class="footer-note">Read-only tools: search_meetings and read_meeting. No network listener, dictation history, private notes, audio, or mutation tools. Remote access requires separate hosting and authorization.</p>`;
 if(name==='Providers')body=`<div class="notice">Optional cloud processing sends the transcript or text you ask to process to your chosen provider. Your provider’s rates and retention policy apply; local processing has no subscription. Murmur does not enable this automatically.</div><div class="settings-form"><label class="check-row">${checkSetting('cloudEnabled')}Enable my cloud provider for writing</label><label>OpenAI-compatible API base URL${textSetting('cloudEndpoint')}</label><label>Model${textSetting('cloudModel')}</label><label>API key<input id="provider-key" type="password" autocomplete="off" placeholder="${state.providerKeySaved?'A protected key is saved':'No key saved'}"></label><div class="row">${button('Save key','saveProviderKey')}${button('Remove key','deleteProviderKey','','quiet danger')}</div></div><p class="footer-note">The key is protected with Windows user-bound encryption. Speech recognition remains local. Enabling cloud writing does not switch models silently.</p>`;
 if(name==='Data and privacy')body=`<div class="settings-group">${settingRow('Keep dictation history','Failed insertions remain recoverable until deleted.',checkSetting('retainHistory'))}${settingRow('Keep dictation audio','Off by default. Failed recordings are retained for retry.',checkSetting('retainAudio'))}${settingRow('History retention (days)','0 keeps history until you delete it. Meeting recordings are retained with their notes.',textSetting('retentionDays','number'))}${settingRow('Detect writing context','Recognize email, messaging and documents from the focused app and field labels. Detection stays local.',checkSetting('detectWritingContext'))}</div><div class="row wrap">${button('Export database','exportData')}${button('Open data folder','openData')}${button('Delete dictation history','clearHistory','','danger')}</div><p class="footer-note">No telemetry or background microphone capture. Models download from the published model repositories. Optional provider and calendar connections are only used when enabled.</p>`;
 if(name==='Updates')body=`<p>Murmur ${escape(state.version)} · Native ${escape(state.architecture)}</p><div class="settings-form"><label>HTTPS release manifest${textSetting('updateFeed')}</label><label>Release public key (PEM)<textarea data-setting="updatePublicKey" rows="5">${escape(s.updatePublicKey)}</textarea></label></div><div class="row">${button('Check for updates','checkUpdates','','primary')}${button('Install verified update','installUpdate','','quiet')}</div><div class="notice">Release hosting and a signing identity have not been configured. This local build and its installers are unsigned. Updates require a manifest signed with the configured public key; downloads are checked before setup runs.</div><div id="update-result"></div>`;
 $('#settings-content').innerHTML=`<h2>${name==='Models'?'Dictation setup':name}</h2>${body}<div class="spacer"></div>${button('Save settings','saveSettings','','primary')}`;
 if(!$('#settings-dialog').open)$('#settings-dialog').showModal();
 if(name==='General'){try{const devices=await call('devices');$('#device-select').innerHTML='<option value="default">System default</option>'+devices.map(d=>`<option value="${escape(d.id)}" ${d.id===s.microphone?'selected':''}>${escape(d.name)}</option>`).join('');}catch(e){notify(e.message);}}
}

function onboarding(){const labels=['Welcome','Models','Microphone','Shortcut','Try it'];let body='';if(onboardStep===0)body=`<canvas class="orb-large" data-orb="searching" data-size="64" data-paused="true" aria-hidden="true"></canvas><h1>Speak your mind.<br>Keep it yours.</h1><p class="lead">Murmur turns your voice into clear writing, anywhere on Windows. Your microphone turns on only when you ask. Your words stay on this PC by default.</p><div class="notice">No account or subscription needed. Download the free speech and writing models once, then work offline.</div>`;if(onboardStep===1)body=`<h1>A voice that works<br>offline, too.</h1><p class="lead">Fast English dictation, speech detection, and local writing. About 1.26 GB to download once. Models load when you start speaking and unload after inactivity. Use an arrow to download one component, or Download all below.</p>${modelSetup()}`;if(onboardStep===2)body=`<h1>Let’s hear you.</h1><p class="lead">Check the Windows default microphone with a short, visible test. Test audio is deleted immediately.</p><div class="meter" style="height:12px;margin:30px 0"><i id="mic-level"></i></div>${button('Test microphone · 5 seconds','testMic','','primary')}<p class="footer-note">If Windows blocks access, enable microphone access for desktop apps in Windows Settings. Murmur cannot change that permission for you.</p>`;if(onboardStep===3)body=`<h1>A shortcut<br>to your own words.</h1><p class="lead">Hold <span class="key">${escape(state.settings.holdShortcut)}</span> to dictate.<br>Press <span class="key">${escape(state.settings.toggleShortcut)}</span> for hands-free.<br>Press <span class="key">Esc</span> to cancel.</p><p>Double-tap Caps Lock to start hands-free recording; tap Caps Lock once to finish. The bar stays hidden at other times. Shortcuts can be changed in Settings.</p>${button('Customize shortcuts','generalSettings')}`;if(onboardStep===4)body=`<h1>Make yourself heard.</h1><p class="lead">Open a text field in another app, double-tap Caps Lock, and speak. Tap Caps Lock once to finish. Or test the recorder here and copy the result from History.</p>${button('Try dictation','record','data-mode="dictation"','primary')}<p class="footer-note">Nothing is submitted automatically. If focus changes, Murmur saves your words and offers Copy or Retry.</p>`;$('#main').innerHTML=`<div class="onboarding"><div class="onboard-steps">${labels.map((s,i)=>`<span class="${i===onboardStep?'active':''}">${s}</span>`).join('')}</div>${body}<div class="onboard-actions">${button(onboardStep?'Back':'Skip setup',onboardStep?'onboardBack':'finishSetup','','quiet')}${button(onboardStep===4?'Open Murmur':'Continue',onboardStep===4?'finishSetup':'onboardNext','','primary')}</div></div>`;refreshOrbs();}
function modal(title,fields,onSave,saveLabel='Save'){const dialog=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-title"><h2>${title}</h2><button type="button" class="icon" data-close="dialog" aria-label="Close dialog">×</button></div><div class="fields">${fields}</div><p id="dialog-error" class="error-text"></p><div class="dialog-actions"><button type="button" data-close="dialog">Cancel</button><button type="submit" class="primary">${saveLabel}</button></div>`;$('#dialog-form').onsubmit=async e=>{e.preventDefault();const save=e.submitter;save.disabled=true;try{await onSave();dialog.close();}catch(error){$('#dialog-error').textContent=error.message;}finally{save.disabled=false;}};dialog.showModal();}
function field(label,id,value='',multiline=false){return `<label>${label}${multiline?`<textarea id="${id}">${escape(value)}</textarea>`:`<input id="${id}" value="${escape(value)}">`}</label>`;}
function confirmAction(title,message,action){modal(title,`<p>${escape(message)}</p>`,action,'Confirm');}
function editEntry(kind,id){const e=(kind==='dictionary'?state.dictionary:state.snippets).find(x=>x.id===id)||{id:crypto.randomUUID(),kind,trigger:'',value:'',shared:false};modal(id?'Edit '+kind:'Add '+(kind==='dictionary'?'a word':'a snippet'),field(kind==='dictionary'?'Word or recurring misspelling':'Spoken phrase','entry-trigger',e.trigger)+field(kind==='dictionary'?'Correct spelling':'Replacement text','entry-value',e.value,kind==='snippet')+`<label class="check-row"><input type="checkbox" id="entry-shared" ${e.shared?'checked':''}>Share through my configured library</label>`,async()=>run('saveEntry',{...e,trigger:$('#entry-trigger').value.trim(),value:$('#entry-value').value,shared:$('#entry-shared').checked}));}
function editTransform(id){const t=state.transforms.find(x=>x.id===id)||{id:crypto.randomUUID(),name:'',prompt:'',samples:[]};modal('Custom transform',field('Name','transform-name',t.name)+field('Instructions','transform-prompt',t.prompt,true)+field('Writing samples · separate with a line containing ---','transform-samples',(t.samples||[]).join('\n---\n'),true),()=>run('saveTransform',{...t,name:$('#transform-name').value,prompt:$('#transform-prompt').value,samples:$('#transform-samples').value.trim()?$('#transform-samples').value.split(/\n---\n/):[]}));}
let autosave; const dirtyEditors=new Set();
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search-input'){query=el.value;clearTimeout(autosave);autosave=setTimeout(()=>{const start=el.selectionStart;render();const input=$('#search-input');input?.focus();input?.setSelectionRange(start,start);},220);}if(el.id==='transcript-search')$('#segments').innerHTML=segments((note.segments||[]).filter(s=>(s.text+' '+s.speaker).toLowerCase().includes(el.value.toLowerCase())));if(['scratchpad-editor','note-editor','summary-editor','note-title'].includes(el.id)){dirtyEditors.add(el.id);clearTimeout(autosave);autosave=setTimeout(()=>saveEditor(el.id),500);}});
async function saveEditor(id){
 clearTimeout(autosave);
 try{
  if(id==='scratchpad-editor'){
   if(!dirtyEditors.has(id))return true;
   const captured=$('#scratchpad-editor')?.value??state.scratchpad;
   await call('scratchpad',{text:captured});state.scratchpad=captured;
   if($('#scratchpad-editor')?.value===captured)dirtyEditors.delete(id);
  }else if(note){
   const args={id:note.id},captured=[];
   for(const [elementId,key] of [['note-editor','notes'],['summary-editor','summary'],['note-title','title']]){
    const element=$('#'+elementId);if(element&&dirtyEditors.has(elementId)){args[key]=element.value;captured.push([elementId,element.value]);}
   }
   if(!captured.length)return true;
   const saved=await call('saveMeeting',args);if(note?.id===args.id)note=saved;
   for(const [elementId,value] of captured)if($('#'+elementId)?.value===value)dirtyEditors.delete(elementId);
  }
  return true;
 }catch(e){notify('Could not save: '+e.message);return false;}
}
document.addEventListener('change',async e=>{try{if(page==='style'&&e.target.dataset.setting){state.settings[e.target.dataset.setting]=e.target.value;await run('saveSettings',state.settings);}if(e.target.id==='style-select'){state.settings.style=e.target.value;await run('saveSettings',state.settings);}if(e.target.id==='note-folder'){note=await call('saveMeeting',{id:note.id,folderId:e.target.value});}}catch{}});
document.addEventListener('click',async e=>{
 const el=e.target.closest('button');if(!el)return;
 if(el.dataset.close){$('#'+el.dataset.close).close();return;}
 if(el.dataset.page){if(!await saveEditor(page==='scratchpad'?'scratchpad-editor':'note-editor'))return;document.body.classList.remove('sidebar-open');page=el.dataset.page;note=null;query='';searchOpen=false;render();return;}
 if(el.dataset.settingPage){await openSettings(el.dataset.settingPage);return;}
 if(el.dataset.window){if(!await saveEditor(page==='scratchpad'?'scratchpad-editor':'note-editor'))return;if(el.dataset.window==='close')setOrbHostState(false,lowPower,state?.settings.orbAnimation);call('window',{command:el.dataset.window});return;}
 if(!el.dataset.action)return;
 const a=el.dataset.action,id=el.dataset.id,kind=el.dataset.kind,originalMarkup=el.innerHTML;
 try{
  if(a==='editEntry'){editEntry(kind,id);return;}if(a==='editTransform'){editTransform(id);return;}
  if(a==='search'){searchOpen=!searchOpen;query='';render();$('#search-input')?.focus();return;}
  if(a==='sortLibrary'){(page==='dictionary'?state.dictionary:state.snippets).reverse();render();return;}
  if(a==='libraryTab'){libraryTab=el.dataset.value;render();return;}
  if(a==='setCleanup'){await run('saveSettings',{...state.settings,cleanup:el.dataset.value});return;}
  if(a==='removeAppStyle'){await run('saveSettings',{...state.settings,appStyles:state.settings.appStyles.filter((_,i)=>i!==Number(el.dataset.index))});return;}
  if(a==='appStyle'){modal('Style by application',field('Process name, without .exe (for example, msedge)','app-process')+field('Category','app-category','work')+`<label>Style<select id="app-style"><option>formal</option><option>casual</option><option>very casual</option><option>excited</option></select></label>`,()=>run('saveSettings',{...state.settings,appStyles:[...state.settings.appStyles,{process:$('#app-process').value.replace(/\.exe$/i,''),category:$('#app-category').value,style:$('#app-style').value}]}));return;}
  if(['models','generalSettings','notetakerSettings','calendarSettings'].includes(a)){await openSettings({models:'Models',generalSettings:'General',notetakerSettings:'Notetaker',calendarSettings:'Calendar'}[a]);return;}
  if(a==='saveSettings'){const settings={...state.settings};$$('#settings-content [data-setting]').forEach(x=>settings[x.dataset.setting]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value):x.value);await run('saveSettings',settings,false);notify('Settings saved.');return;}
  if(a==='saveProviderKey'){await run(a,{key:$('#provider-key').value},false);$('#provider-key').value='';state.providerKeySaved=true;notify('Key protected by Windows.');return;}
  if(a==='onboardNext'){onboardStep++;onboarding();return;}if(a==='onboardBack'){onboardStep--;onboarding();return;}if(a==='finishSetup'){await run('saveSettings',{...state.settings,onboarded:true});return;}
  if(a==='repairSetup'){if(modelDownloads.busy)return;modelMaintenance=true;refreshModelDownloads();el.innerHTML=busy('Checking dictation setup…','connecting');try{modelDownloads.states.clear();await call('repairSetup');state=await call('refresh');await openSettings('Models');}finally{modelMaintenance=false;refreshModelDownloads();}return;}
  if(a==='downloadSpeakers'){el.disabled=true;el.innerHTML=busy('Setting up speakers…','connecting');await modelDownloads.enqueue(['speaker-segmentation.int8.onnx','3dspeaker_speech_eres2net_base_sv_zh-cn_3dspeaker_16k.onnx']);await openSettings('Notetaker');return;}
  if(a==='downloadRecommended'){if(!modelMaintenance)modelDownloads.enqueue(dictationFiles);return;}
  if(a==='modelDownload'){if(!modelMaintenance)modelDownloads.enqueue([el.dataset.file]);return;}
  if(a==='modelDelete'){confirmAction('Remove model?','This frees disk space. You can download it again.',async()=>{await call(a,{file:el.dataset.file});state=await call('refresh');await openSettings('Models');});return;}
  if(a==='modelCancel'){await modelDownloads.cancel();return;}
  if(a==='testMic'){el.disabled=true;el.innerHTML=busy('Listening for 5 seconds…','listening');const result=await call(a,{device:$('#device-select')?.value||state.settings.microphone});notify(result.message);el.disabled=false;el.textContent='Test microphone';return;}
  if(a==='record'){await call(a,{mode:el.dataset.mode||'dictation',meetingId:el.dataset.meetingId||''});state=await call('refresh');if(el.dataset.mode==='meeting'){note=await call('meeting',{id:state.recording.id});noteTab='notes';page='notetaker';}render();return;}
  if(a==='openNote'){if(!await saveEditor('note-editor'))return;note=await call('meeting',{id});noteTab='notes';page='notetaker';render();return;}if(a==='backNotes'){if(!await saveEditor('note-editor'))return;note=null;state=await call('refresh');render();return;}
  if(a==='noteTab'){if(!await saveEditor('note-editor'))return;noteTab=el.dataset.value;render();return;}
  if(a==='newNote'){note=await call('saveMeeting',{id:crypto.randomUUID(),title:'Untitled note',notes:''});noteTab='notes';render();return;}
  if(a==='foldersTab'){modal('Folders',`<div class="stack">${state.folders.map(f=>`<div class="row spread"><button type="button" data-action="openFolder" data-id="${f.id}">${escape(f.name)}</button><button type="button" class="small quiet" data-action="editFolder" data-id="${f.id}">Edit</button><button type="button" class="danger small" data-action="deleteFolder" data-id="${f.id}">Delete</button></div>`).join('')}</div>${field('New folder name','folder-name')}${field('Description','folder-description')}<label class="check-row"><input type="checkbox" id="folder-shared">Share this folder’s transcripts and summaries through my configured library</label>`,()=>run('saveFolder',{id:crypto.randomUUID(),name:$('#folder-name').value,description:$('#folder-description').value,shared:$('#folder-shared').checked}),'Create folder');return;}
  if(a==='openFolder'){selectedFolder=id;$('#dialog').close();render();return;}if(a==='clearFolder'){selectedFolder='';render();return;}if(a==='notesTab'){selectedFolder='';render();return;}
  if(a==='editFolder'){const f=state.folders.find(x=>x.id===id);modal('Edit folder',field('Name','folder-name',f.name)+field('Description','folder-description',f.description)+`<label class="check-row"><input type="checkbox" id="folder-shared" ${f.shared?'checked':''}>Share transcripts and summaries in this folder</label>`,()=>run('saveFolder',{...f,name:$('#folder-name').value,description:$('#folder-description').value,shared:$('#folder-shared').checked}));return;}
  if(a==='speakerName'){modal('Rename a speaker',`<label>Current label<select id="speaker-from">${[...new Set((note.segments||[]).map(s=>s.speaker))].map(s=>`<option>${escape(s)}</option>`).join('')}</select></label>${field('Name','speaker-to')}`,async()=>{note=await call('renameSpeaker',{id:note.id,from:$('#speaker-from').value,to:$('#speaker-to').value});render();});return;}
  if(a==='summarize'){if(note.summaryEdited){confirmAction('Replace edited summary?','Your personal notes will stay unchanged.',async()=>{el.innerHTML=busy('Composing…','composing');note=await call('summarize',{id});render();});return;}el.innerHTML=busy('Composing…','composing');el.disabled=true;note=await call(a,{id});render();return;}
  if(a==='ask'){const question=$('#ask-input').value;if(!question.trim())return;$('#answer').innerHTML=busy('Looking through your notes…','searching');el.disabled=true;const answer=await call(a,{question,meetingId:el.dataset.meetingId||''});$('#answer').innerHTML=`<div class="quote">${escape(answer.answer)}</div><div class="source-links">${answer.sources.map(s=>button(`[${s.number}] ${escape(s.title)}`,'openNote',`data-id="${s.id}"`,'small')).join('')}</div>`;el.disabled=false;return;}
  if(a==='openScratchpad'){page='scratchpad';render();return;}
  if(a==='copyScratchpad'){await call('copy',{text:$('#scratchpad-editor').value});notify('Copied.');return;}
  if(a==='useTransform'||a==='polishScratchpad'){let source=$('#scratchpad-editor')?.value??state.scratchpad;const t=id==='prompt'?{prompt:'Rewrite as a clear structured prompt with context, task, and constraints. Do not invent facts.'}:state.transforms.find(t=>t.id===id)||{prompt:'Polish this writing. Improve clarity and conciseness while preserving every fact.'};if(!source.trim()){page='scratchpad';render();notify('Add text to Scratchpad first.');return;}page='scratchpad';state.scratchpad=source;render();$('#transform-result').innerHTML=busy('Composing…','composing');const result=await call('transform',{text:source,prompt:t.prompt,id:t.id||id||''});state.scratchpad=result.result;render();$('#transform-result').innerHTML=`<h3>Changes</h3><div class="comparison"><div>${escape(result.original)}</div><div>${escape(result.result)}</div></div>`;return;}
  if(a==='undoTransform'){const result=await call(a);state.scratchpad=result.text;render();return;}
  if(a==='recordEvent'){await run(a,{id});note=await call('meeting',{id:state.recording.id});page='notetaker';noteTab='notes';render();return;}if(a==='calendarConnect'){el.disabled=true;$('#calendar-result').innerHTML=busy('Waiting for your browser…','connecting');const result=await call(a,{provider:$('#calendar-provider').value,clientId:$('#calendar-client').value,clientSecret:$('#calendar-secret').value});$('#calendar-secret').value='';$('#calendar-result').textContent=result.message;el.disabled=false;return;}
  if(a==='calendarRefresh'){el.disabled=true;$('#calendar-result').innerHTML=busy('Refreshing…','connecting');const result=await call(a,{provider:$('#calendar-provider').value});$('#calendar-result').innerHTML=result.map(v=>`<p><strong>${escape(v.title)}</strong><br>${escape(v.start)}</p>`).join('')||'No upcoming events.';el.disabled=false;return;}
  if(a==='calendarDisconnect'){await call(a,{provider:$('#calendar-provider').value});notify('Calendar disconnected. Saved notes were kept.');return;}
  if(a==='checkUpdates'){el.disabled=true;$('#update-result').innerHTML=busy('Checking…','connecting');const result=await call(a);$('#update-result').textContent=result.message;el.disabled=false;return;}
  if(a.startsWith('delete')||a==='clearHistory'){confirmAction('Delete this data?',a==='clearHistory'?'This removes saved dictations and their audio. Meetings and models are kept.':'This deletion cannot be undone.',async()=>{await run(a,{id,kind});if(a==='deleteMeeting')note=null;render();});return;}
  const args={id,kind,file:el.dataset.file,mode:el.dataset.mode,track:Number(el.dataset.track||0)};el.disabled=true;
  if(['retryTranscription','importAudio','stop','sync'].includes(a))el.innerHTML=busy(a==='stop'?'Processing…':'Working…',a==='sync'?'connecting':'working');
  const result=await run(a,args);
  if(a==='exportMeeting')notify('Export complete.');if(a==='copy'||a==='copyHistory')notify('Copied.');if(a==='sync')notify(result.message);
  el.disabled=false;
 }catch(error){el.disabled=false;el.innerHTML=originalMarkup;for(const selector of ['#calendar-result','#update-result'])if($(selector))$(selector).textContent=error.message;notify(error.message);if($('#answer'))$('#answer').innerHTML=`<p class="error-text">${escape(error.message)}</p>`;if($('#transform-result'))$('#transform-result').textContent=error.message;}
});
function recordingStatus(){const r=state?.recording;if(!r)return;const active=['recording','processing'].includes(r.state);$('#recording-strip').hidden=!active;if(!active)return;$('#recording-strip').innerHTML=r.state==='processing'?busy('Thinking…','searching')+button('Cancel','cancel','','small'):`<span class="status-dot"></span><span id="record-timer">Recording</span>${button('Stop','stop','','small')}${button('×','cancel','','small')}`;}
window.chrome.webview.addEventListener('message',async event=>{const {type,data}=event.data;if(type==='flushEditor'){const saved=await saveEditor(page==='scratchpad'?'scratchpad-editor':'note-editor');await call('editorFlushed',{saved});return;}if(type==='response'){const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(new Error(data.error)):p.resolve(data.result);return;}if(type==='snapshot'){state=data;setOrbHostState(hostVisible,lowPower,state.settings.orbAnimation);if(note&&data.recording.state!=='recording'&&data.recording.state!=='processing'){const currentId=note.id;if(!await saveEditor('note-editor'))return;let fresh;try{fresh=await call('meeting',{id:currentId});}catch(e){notify(e.message);note=null;render();return;}if(note?.id===currentId){note=fresh;if(!dirtyEditors.size)render();}return;}if(!$('#dialog').open&&!$('#settings-dialog').open&&!['scratchpad'].includes(page)&&!note)render();}if(type==='recording'){if(state)state.recording=data;recordingStatus();if(data.error)notify(data.error);}if(type==='notice')notify(data.message);if(type==='tick'&&$('#record-timer'))$('#record-timer').textContent=duration(data.elapsed);if(type==='level'&&$('#mic-level'))$('#mic-level').style.transform=`scaleX(${Math.min(1,data.level*4)})`;if(type==='download')modelDownloads.update(data);if(type==='visibility'){hostVisible=data.active;setOrbHostState(hostVisible,lowPower,state?.settings.orbAnimation);}if(type==='power'){lowPower=data.lowPower;setOrbHostState(hostVisible,lowPower,state?.settings.orbAnimation);}});
$('#settings').onclick=()=>openSettings();$('#help').onclick=()=>call('help');$('#collapse').onclick=()=>{if(matchMedia('(max-width: 860px)').matches)document.body.classList.toggle('sidebar-open');else document.body.classList.toggle('collapsed');};$('#account').onclick=()=>notify('Local workspace · No account or subscription required.');$('#notifications').onclick=()=>notify(state.pending.length?`${state.pending.length} recording(s) have recovery data. Check History or Notetaker.`:'You’re all caught up.');$('#theme').onclick=async()=>{await run('saveSettings',{...state.settings,theme:document.documentElement.dataset.theme==='dark'?'light':'dark'});};$('#drag-area').onmousedown=e=>{if(e.detail===2)call('window',{command:'maximize'});else if(e.button===0)call('window',{command:'drag'});};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state?.recording.state==='recording')call('cancel');if((e.ctrlKey||e.metaKey)&&e.key==='n'&&state.settings.onboarded){e.preventDefault();page='notetaker';call('saveMeeting',{id:crypto.randomUUID(),title:'Untitled note',notes:''}).then(m=>{note=m;noteTab='notes';render();});}});
window.murmurDiagnostics=()=>({orbs:orbDiagnostics(),pendingRequests:pending.size,page});
try{state=await call('ready');lowPower=state.lowPower;setOrbHostState(true,lowPower,state?.settings.orbAnimation);render();}catch(e){$('#main').textContent=e.message;}
